style.css:
body {
  background-image: url("https://vinsweb.org/wp-content/uploads/2020/04/AtHome-NightSky-1080x810-1-1024x768.jpg"); /* Replace with your image's path */
  background-size: cover; /* Scales the image to cover the entire container */
  background-repeat: no-repeat; /* Prevents the image from repeating */
  background-position: center center; /* Centers the image horizontally and vertically */
  background-attachment: fixed; /* Keeps the background image fixed when scrolling (optional) */
}
body {
  color: white; /* Sets all text to blue */
}
